-- hrm.tg_roster_lines_published: A line of a published roster is added or changed only with a reason and is never deleted (FR-HRM-ATT-07); refused with constraint ck_roster_lines_published.
create or replace function hrm.tg_roster_lines_published() returns trigger
language plpgsql as $fn$
begin
    if tg_op = 'DELETE' then
        if old.roster_status = 'published' then
            raise exception 'roster line % belongs to a published roster and cannot be deleted', old.id
                using errcode = '23514', constraint = 'ck_roster_lines_published';
        end if;
