            raise exception 'a day added to a published roster needs a reason'
                using errcode = '23514', constraint = 'ck_roster_lines_published';
        end if;
        return new;
    end if;
    if old.roster_status = 'published'
       and (new.shift_id, new.day_type, new.work_date, new.employment_id) is distinct from (old.shift_id, old.day_type, old.work_date, old.employment_id)
       and (new.reason is null or btrim(new.reason) = '') then
        raise exception 'a day of a published roster changes only with a reason'
            using errcode = '23514', constraint = 'ck_roster_lines_published';
    end if;
    return new;
end
